SELECT md.chembl_id AS molecule_chembl_id, md.pref_name AS molecule_name, md.max_phase, md.molecule_type, cs.canonical_smiles FROM molecule_dictionary md INNER JOIN compound_structures cs ON md.molregno = cs.molregno WHERE md.molregno IN (SELECT cr.molregno FROM compound_records cr WHERE cr.doc_id = (SELECT d.doc_id FROM docs d WHERE d.chembl_id = 'CHEMBL1150404')) ORDER BY md.chembl_id ASC
